package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The pools on a sheet, sorted by name, and their members: people of the sheet, each in a pool at most once, or
 * other pools of the sheet, each a member of at most one pool, with a share percent. A pool cannot contain itself
 * through any chain of pools, and a chain is at most three pools deep. A pool's total share counts a retired member's
 * share (a retirement date set, whatever the date) as 0.00; the pool is balanced when its total is exactly 100.00.
 * A pool that is a member of none has the sheet's pot; a pool that is a member of another has as its pot its cut in
 * that pool (none when that pool has no cuts). Each member of a balanced pool with a pot has a cut: the pot times
 * their share divided by 100, rounded half to even to two decimals (0.00 for a retired member); the remainder, the
 * pot less the cuts added up, goes to the member with the largest share, the earliest added on a tie, so the cuts
 * total exactly the pot.
 */
@Service
public class Pools {

    /** The longest a pool's name may be. */
    static final int NAME_MAX = 100;

    /** The most pools a chain of pools, each a member of the one above, may hold. */
    static final int DEPTH_MAX = 3;

    private static final BigDecimal HUNDRED = new BigDecimal("100.00");

    /**
     * A member of a pool as shown: the person (null for a pool), the pool (null for a person), the name, their
     * share, whether they are retired and their cut (null: none).
     */
    public record Member(Long personId, String pool, String name, BigDecimal share, boolean retired, BigDecimal cut) {
    }

    /** A pool as shown: its members in the order they were added, its total share and whether it is balanced. */
    public record Shown(String name, List<Member> members, BigDecimal total, boolean balanced) {
    }

    private final PoolRepository pools;
    private final PoolMemberRepository members;
    private final PersonRepository people;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final ApplicationEventPublisher events;

    public Pools(PoolRepository pools, PoolMemberRepository members, PersonRepository people, SheetService sheets,
            SheetRepository sheetRows, ApplicationEventPublisher events) {
        this.pools = pools;
        this.members = members;
        this.people = people;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.events = events;
    }

    /** The pools on the sheet, sorted by name, each with its members and figures. */
    @Transactional(readOnly = true)
    public List<Shown> list(String sheetId) {
        List<Pool> all = pools.findBySheetIdOrderByNameAsc(sheetId);
        Map<Long, Pool> poolById = all.stream().collect(Collectors.toMap(Pool::getId, Function.identity()));
        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        Map<Long, List<PoolMember>> byPool = members.findByPoolIdInOrderByIdAsc(all.stream().map(Pool::getId).toList())
                .stream().collect(Collectors.groupingBy(PoolMember::getPoolId));
        Map<Long, Long> above = new HashMap<>();
        byPool.values().forEach(ms -> ms.stream().filter(m -> m.getMemberPoolId() != null)
                .forEach(m -> above.put(m.getMemberPoolId(), m.getPoolId())));
        BigDecimal pot = sheets.settings(sheetId).pot();
        Map<Long, Shown> shown = new HashMap<>();
        for (Pool pool : all) {
            show(pool.getId(), poolById, byId, byPool, above, pot, shown, new HashSet<>());
        }
        return all.stream().map(p -> shown.get(p.getId())).toList();
    }

    /** The pool shown with its figures, the pool above it shown first since its cut there is this pool's pot. */
    private Shown show(long poolId, Map<Long, Pool> poolById, Map<Long, Person> byId,
            Map<Long, List<PoolMember>> byPool, Map<Long, Long> above, BigDecimal sheetPot, Map<Long, Shown> shown,
            Set<Long> visiting) {
        Shown done = shown.get(poolId);
        if (done != null) {
            return done;
        }
        Pool pool = poolById.get(poolId);
        BigDecimal pot = sheetPot;
        Long parent = above.get(poolId);
        if (parent != null) {
            pot = null;
            if (poolById.containsKey(parent) && visiting.add(poolId)) {
                Shown up = show(parent, poolById, byId, byPool, above, sheetPot, shown, visiting);
                pot = up.members().stream().filter(m -> pool.getName().equals(m.pool())).map(Member::cut)
                        .filter(Objects::nonNull).findFirst().orElse(null);
            }
        }
        List<Member> listed = new ArrayList<>();
        for (PoolMember m : byPool.getOrDefault(poolId, List.of())) {
            if (m.getMemberPoolId() != null) {
                Pool member = poolById.get(m.getMemberPoolId());
                if (member != null) {
                    listed.add(new Member(null, member.getName(), member.getName(), m.getShare().setScale(2), false,
                            null));
                }
            } else if (byId.containsKey(m.getPersonId())) {
                Person p = byId.get(m.getPersonId());
                listed.add(new Member(p.getId(), null, p.getName(), m.getShare().setScale(2), p.isRetired(), null));
            }
        }
        BigDecimal total = listed.stream().filter(m -> !m.retired()).map(Member::share)
                .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
        boolean balanced = total.compareTo(HUNDRED) == 0;
        Shown result = new Shown(pool.getName(), balanced && pot != null ? cut(listed, pot) : listed, total, balanced);
        shown.put(poolId, result);
        return result;
    }

    /** The members, in the order added, each with their cut of the pot; the remainder goes to the largest share. */
    private static List<Member> cut(List<Member> shown, BigDecimal pot) {
        List<BigDecimal> cuts = new ArrayList<>();
        int largest = -1;
        for (int i = 0; i < shown.size(); i++) {
            Member m = shown.get(i);
            cuts.add(m.retired() ? BigDecimal.ZERO.setScale(2)
                    : pot.multiply(m.share()).divide(HUNDRED, 2, RoundingMode.HALF_EVEN));
            if (!m.retired() && (largest < 0 || m.share().compareTo(shown.get(largest).share()) > 0)) {
                largest = i;
            }
        }
        if (largest >= 0) {
            BigDecimal sum = cuts.stream().reduce(BigDecimal.ZERO, BigDecimal::add);
            cuts.set(largest, cuts.get(largest).add(pot.subtract(sum)).setScale(2));
        }
        List<Member> cut = new ArrayList<>();
        for (int i = 0; i < shown.size(); i++) {
            Member m = shown.get(i);
            cut.add(new Member(m.personId(), m.pool(), m.name(), m.share(), m.retired(), cuts.get(i)));
        }
        return cut;
    }

    /** Add a pool under its name, trimmed; refused when the name is blank, too long or already a pool's. */
    @Transactional
    public void add(String sheetId, String user, String text) {
        String name = text == null ? "" : text.strip();
        if (name.isEmpty()) {
            throw new PoolRefused("Enter a name for the pool.");
        }
        if (name.length() > NAME_MAX) {
            throw new PoolRefused("The pool's name is too long.");
        }
        sheets.load(sheetId, user);
        sheetRows.lockById(sheetId);
        if (pools.findBySheetIdAndName(sheetId, name).isPresent()) {
            throw new PoolRefused("There is already a pool named " + name + ".");
        }
        pools.saveAndFlush(new Pool(sheetId, name));
        events.publishEvent(new PoolAdded(sheetId, user, name));
    }

    /**
     * Add a person of the sheet to the named pool with a share of two decimals, more than 0.00 and at most 100.00;
     * refused when the person is in the pool already.
     */
    @Transactional
    public void addMember(String sheetId, String user, String poolName, long personId, String text) {
        BigDecimal share = share(text);
        sheetRows.lockById(sheetId);
        Pool pool = pool(sheetId, poolName);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new PoolRefused("Choose a person on this sheet."));
        if (members.existsByPoolIdAndPersonId(pool.getId(), person.getId())) {
            throw new PoolRefused(person.getName() + " is in the pool already.");
        }
        members.saveAndFlush(new PoolMember(pool.getId(), person.getId(), share));
        events.publishEvent(new PoolMemberAdded(sheetId, user, pool.getName(), person.getName(), share));
    }

    /**
     * Add another pool of the sheet to the named pool with a share like a person's; refused when the member is the
     * pool itself or contains it through any chain, is a member of a pool already, or the chain would be more than
     * three pools deep.
     */
    @Transactional
    public void addPoolMember(String sheetId, String user, String poolName, String memberName, String text) {
        BigDecimal share = share(text);
        sheetRows.lockById(sheetId);
        Pool pool = pool(sheetId, poolName);
        Pool member = pools.findBySheetIdAndName(sheetId, memberName == null ? "" : memberName.strip())
                .orElseThrow(() -> new PoolRefused("Choose a pool on this sheet."));
        List<Pool> all = pools.findBySheetIdOrderByNameAsc(sheetId);
        Map<Long, Long> above = new HashMap<>();
        Map<Long, List<Long>> below = new HashMap<>();
        members.findByPoolIdInOrderByIdAsc(all.stream().map(Pool::getId).toList()).stream()
                .filter(m -> m.getMemberPoolId() != null).forEach(m -> {
                    above.put(m.getMemberPoolId(), m.getPoolId());
                    below.computeIfAbsent(m.getPoolId(), k -> new ArrayList<>()).add(m.getMemberPoolId());
                });
        int levelsAbove = 1;
        boolean contains = member.getId().equals(pool.getId());
        Set<Long> seen = new HashSet<>(List.of(pool.getId()));
        for (Long up = above.get(pool.getId()); up != null && seen.add(up); up = above.get(up)) {
            levelsAbove++;
            contains |= up.equals(member.getId());
        }
        if (contains) {
            throw new PoolRefused("A pool cannot contain itself.");
        }
        if (above.containsKey(member.getId())) {
            throw new PoolRefused(member.getName() + " is a member of a pool already.");
        }
        if (levelsAbove + depth(member.getId(), below, new HashSet<>()) > DEPTH_MAX) {
            throw new PoolRefused("A chain of pools is at most " + DEPTH_MAX + " deep.");
        }
        members.saveAndFlush(PoolMember.ofPool(pool.getId(), member.getId(), share));
        events.publishEvent(new PoolMemberAdded(sheetId, user, pool.getName(), member.getName(), share));
    }

    /** How many pools deep the chain is from this pool down: 1 when no pool is a member of it. */
    private static int depth(long poolId, Map<Long, List<Long>> below, Set<Long> seen) {
        if (!seen.add(poolId)) {
            return 0;
        }
        int deepest = 0;
        for (long child : below.getOrDefault(poolId, List.of())) {
            deepest = Math.max(deepest, depth(child, below, seen));
        }
        return 1 + deepest;
    }

    private Pool pool(String sheetId, String poolName) {
        return pools.findBySheetIdAndName(sheetId, poolName == null ? "" : poolName.strip())
                .orElseThrow(() -> new PoolRefused("No such pool on this sheet."));
    }

    private static BigDecimal share(String text) {
        String s = text == null ? "" : text.strip();
        if (!s.matches("\\d{1,3}(\\.\\d{1,2})?")) {
            throw new PoolRefused("Enter a share with up to two decimals.");
        }
        BigDecimal share = new BigDecimal(s).setScale(2);
        if (share.signum() <= 0 || share.compareTo(HUNDRED) > 0) {
            throw new PoolRefused("A share is more than 0.00 and at most 100.00.");
        }
        return share;
    }
}
package net.officefloor.hq.app.pool;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.util.List;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The pools on a sheet and their members. The signed-in user's name comes in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/pools")
@Validated
public class PoolController {

    /** A pool to add: a name (blank is refused). */
    public record PoolForm(@Size(max = 1000) String name) {
    }

    /**
     * A member to add to the named pool: a person of the sheet, or else another pool of the sheet by name, and the
     * share percent.
     */
    public record MemberForm(@NotBlank @Size(max = 1000) String pool, Long personId,
            @Size(max = 1000) String memberPool, @Size(max = 100) String share) {
    }

    /**
     * A member of a pool: a person (pool null) or a pool (personId null); the share with two decimals, and so the
     * cut, null when the member has none.
     */
    public record MemberView(Long personId, String pool, String name, String share, boolean retired, String cut) {
    }

    /** A pool on the sheet; its total share with two decimals. */
    public record PoolView(String name, List<MemberView> members, String total, boolean balanced) {

        static PoolView of(Pools.Shown p) {
            return new PoolView(p.name(), p.members().stream()
                    .map(m -> new MemberView(m.personId(), m.pool(), m.name(), m.share().toPlainString(), m.retired(),
                            m.cut() == null ? null : m.cut().toPlainString())).toList(),
                    p.total().toPlainString(), p.balanced());
        }
    }

    public record Refusal(String message) {
    }

    private final Pools pools;

    public PoolController(Pools pools) {
        this.pools = pools;
    }

    @GetMapping
    public List<PoolView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return pools.list(sheetId.trim()).stream().map(PoolView::of).toList();
    }

    /** Add a pool; answers with every pool on the sheet. */
    @PostMapping
    public List<PoolView> add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody PoolForm form) {
        String sheet = sheetId.trim();
        pools.add(sheet, user.trim(), form.name());
        return list(sheet);
    }

    /** Add a member to a pool; answers with every pool on the sheet. */
    @PostMapping("/members")
    public List<PoolView> addMember(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody MemberForm form) {
        String sheet = sheetId.trim();
        if (form.personId() != null) {
            pools.addMember(sheet, user.trim(), form.pool(), form.personId(), form.share());
        } else if (form.memberPool() != null && !form.memberPool().isBlank()) {
            pools.addPoolMember(sheet, user.trim(), form.pool(), form.memberPool(), form.share());
        } else {
            throw new PoolRefused("Choose a person or a pool.");
        }
        return list(sheet);
    }

    @ExceptionHandler(PoolRefused.class)
    public ResponseEntity<Refusal> refused(PoolRefused e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new Refusal(e.getMessage()));
    }

    /** Another user added the same pool, or the same member, at the same moment: this one is refused. */
    @ExceptionHandler(DataIntegrityViolationException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void taken() {
    }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Component, effect, inject, input, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { PersonWithClaims } from '../claims/claims';

const SHARE = /^\d{1,3}(\.\d{1,2})?$/;

/**
 * A member of a pool: a person (pool null) or another pool (personId null), the share (two decimals), whether they
 * are retired and their cut of the pool's pot.
 */
export interface PoolMember {
  personId: number | null;
  pool: string | null;
  name: string;
  share: string;
  retired: boolean;
  /** Two decimals; null in an unbalanced pool or when the sheet has no pot. */
  cut: string | null;
}

/** A pool: its members, its total share (a retired member's counting 0.00) and whether that is exactly 100.00. */
export interface Pool {
  name: string;
  members: PoolMember[];
  total: string;
  balanced: boolean;
}

/** What is typed into a pool's member form (a person's id, or pool:<name>), and why its last add was refused. */
interface Draft {
  personId: string;
  share: string;
  error: string;
}

const EMPTY: Draft = { personId: '', share: '', error: '' };

// The sheet's pools, sorted by name, each with its members and their shares, its total share and whether it is
// balanced, and each member's cut of the pool's pot (none unless the pool is balanced and has a pot); the form that adds a pool, and on each pool's row the form that adds a person, or another pool, to it with a share.
// A person can be in several pools, each at most once; a pool is a member of at most one pool, and then its pot is
// its cut there, while a pool that is a member of none has the sheet's pot.
@Component({
  selector: 'app-pools',
  template: `
    <section aria-label="Pools">
      <h2>Pools</h2>
      <ul>
        @for (p of pools(); track p.name) {
          <li [attr.data-testid]="'pool-row-' + p.name">
            <span data-testid="pool-name">{{ p.name }}</span>
            <span>Total share <span data-testid="pool-total-share">{{ p.total }}</span></span>
            <span>Balanced <span data-testid="pool-balanced">{{ p.balanced ? 'yes' : 'no' }}</span></span>
            <ul>
              @for (m of p.members; track memberKey(m)) {
                <li [attr.data-testid]="'pool-member-' + p.name + '-' + memberKey(m)">
                  <span data-testid="pool-member-name">{{ m.name }}</span>
                  <span>Share <span data-testid="pool-share">{{ m.share }}</span></span>
                  <span>Cut <span data-testid="pool-cut">{{ m.cut ?? '' }}</span></span>
                  @if (m.retired) {
                    <span>(retired)</span>
                  }
                </li>
              }
            </ul>
            <form (submit)="addMember($event, p.name)" [attr.aria-label]="'Add member to pool ' + p.name">
              <label [for]="'pool-member-select-' + p.name">Person or pool</label>
              <select
                [id]="'pool-member-select-' + p.name"
                data-testid="pool-member-select"
                [value]="draft(p.name).personId"
                (change)="edit(p.name, { personId: value($event) })"
              >
                <option value="" [selected]="draft(p.name).personId === ''">Choose a person or pool</option>
                @for (person of people(); track person.id) {
                  <option [value]="'' + person.id" [selected]="draft(p.name).personId === '' + person.id">
                    {{ person.name }}
                  </option>
                }
                @for (other of pools(); track other.name) {
                  <option [value]="'pool:' + other.name" [selected]="draft(p.name).personId === 'pool:' + other.name">
                    pool:{{ other.name }}
                  </option>
                }
              </select>
              <label [for]="'pool-member-share-' + p.name">Share %</label>
              <input
                [id]="'pool-member-share-' + p.name"
                data-testid="pool-member-share"
                inputmode="decimal"
                [value]="draft(p.name).share"
                (input)="edit(p.name, { share: value($event) })"
              />
              <button type="submit" data-testid="pool-member-add">Add member</button>
              @if (draft(p.name).error) {
                <p role="alert" data-testid="pool-error">{{ draft(p.name).error }}</p>
              }
            </form>
          </li>
        }
      </ul>
      <form (submit)="add($event)" aria-label="Add pool">
        <label for="pool-form-name">Name</label>
        <input
          id="pool-form-name"
          data-testid="pool-form-name"
          [value]="name()"
          (input)="name.set(value($event)); error.set('')"
        />
        <button type="submit" data-testid="pool-form-submit">Add pool</button>
        @if (error()) {
          <p role="alert" data-testid="pool-form-error">{{ error() }}</p>
        }
      </form>
    </section>
  `,
})
export class Pools {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** Everyone on the sheet, retired people included: the choices for a member, re-read as they change. */
  readonly people = input.required<PersonWithClaims[]>();

  protected readonly pools = signal<Pool[]>([]);
  protected readonly name = signal('');
  protected readonly error = signal('');
  protected readonly drafts = signal<Record<string, Draft>>({});
  /** Each answer is numbered: one older than the last shown is dropped. */
  private asked = 0;
  private shown = 0;
  /** A submit still waiting for its answer: another press meanwhile is ignored. */
  private busy = false;

  constructor() {
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loads();
      this.pools.set([]);
      this.name.set('');
      this.error.set('');
      this.drafts.set({});
      if (sheet) void this.reload(sheet);
    });
    // a member's retirement changes the pool's total: re-read the pools whenever the people change
    effect(() => {
      this.people();
      const sheet = this.session.sheet();
      if (sheet) void this.reload(sheet);
    });
  }

  protected value(e: Event): string {
    return (e.target as HTMLInputElement | HTMLSelectElement).value;
  }

  /** A member's part of its row's test id: the person's id, or pool-<name> for a pool. */
  protected memberKey(m: PoolMember): string {
    return m.pool !== null ? 'pool-' + m.pool : '' + m.personId;
  }

  protected draft(pool: string): Draft {
    return this.drafts()[pool] ?? EMPTY;
  }

  protected edit(pool: string, change: Partial<Draft>): void {
    this.drafts.update((all) => ({ ...all, [pool]: { ...(all[pool] ?? EMPTY), ...change, error: '' } }));
  }

  protected async add(e: Event): Promise<void> {
    e.preventDefault();
    if (this.busy) return;
    this.error.set('');
    const name = this.name().trim();
    if (name === '') {
      this.error.set('Enter a name for the pool.');
      return;
    }
    this.busy = true;
    try {
      const refusal = await this.post('', { name });
      if (refusal) this.error.set(refusal);
      else this.name.set('');
    } finally {
      this.busy = false;
    }
  }

  protected async addMember(e: Event, pool: string): Promise<void> {
    e.preventDefault();
    if (this.busy) return;
    const draft = this.draft(pool);
    this.edit(pool, {});
    const share = draft.share.trim();
    let refusal = '';
    if (draft.personId === '') {
      refusal = 'Choose a person or a pool.';
    } else if (!SHARE.test(share) || Number(share) <= 0 || Number(share) > 100) {
      refusal = 'Enter a share with up to two decimals, more than 0.00 and at most 100.00.';
    } else {
      this.busy = true;
      try {
        const member = draft.personId.startsWith('pool:')
          ? { memberPool: draft.personId.slice('pool:'.length) }
          : { personId: Number(draft.personId) };
        refusal = await this.post('/members', { pool, ...member, share });
      } finally {
        this.busy = false;
      }
    }
    if (refusal) this.drafts.update((all) => ({ ...all, [pool]: { ...(all[pool] ?? EMPTY), error: refusal } }));
    else this.drafts.update((all) => ({ ...all, [pool]: EMPTY }));
  }

  /** Post a change: '' once made (the pools shown as they now stand), else why it was refused. */
  private async post(path: string, body: object): Promise<string> {
    const sheet = this.session.sheet();
    if (!sheet) return 'Load a sheet first.';
    const headers = { 'X-User': this.session.user() ?? '' };
    const n = ++this.asked;
    try {
      const pools = await firstValueFrom(
        this.http.post<Pool[]>(`/api/sheets/${encodeURIComponent(sheet)}/pools${path}`, body, { headers }),
      );
      this.show(sheet, n, pools);
      return '';
    } catch (err) {
      const answer = err instanceof HttpErrorResponse ? err : null;
      return answer?.error?.message ?? 'Could not save the pool.';
    }
  }

  private async reload(sheet: string): Promise<void> {
    const n = ++this.asked;
    const pools = await firstValueFrom(this.http.get<Pool[]>(`/api/sheets/${encodeURIComponent(sheet)}/pools`));
    this.show(sheet, n, pools);
  }

  private show(sheet: string, n: number, pools: Pool[]): void {
    if (this.session.sheet() !== sheet || n < this.shown) return;
    this.shown = n;
    this.pools.set(pools);
  }
}
