          data-testid="person-form-terms"
          inputmode="numeric"
          [value]="terms()"
          (input)="terms.set(value($event)); error.set('')"
        />
        <label for="person-form-contact">Contact (blank: none)</label>
        <input
          id="person-form-contact"
